&reftitle.description;

 public Yaf_Route_Map::__construct
 stringcontroller_prefer&false;
 stringdelimiter""


 Construye una ruta map. Una ruta map asocia el URI completo a un nombre de
 controlador o a un nombre de acción.

  &reftitle.examples;

   Ejemplo de Yaf_Route_Map


<?php
/**
 * Añade una ruta map a la pila de rutas de Yaf_Router
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute("name",
    new Yaf_Route_Map());
?>


   &example.outputs.similar;


/* para http://yourdomain.com/product/foo/bar
 * la petición llevará los siguientes valores:
 */
array(
  "action" => "product_foo_bar",
)




   Ejemplo de Yaf_Route_Map


<?php
/**
 * Añade a la pila de rutas de Yaf_Router una ruta map con delimitador
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute("name",
    new Yaf_Route_Map(true, "_"));
?>


   &example.outputs.similar;


/* para http://yourdomain.com/user/list/_/foo/22
 * la petición llevará los siguientes valores:
 */
array(
    "controller" => "User_List",
)

/**
 * y los parámetros de petición:
 */
array(
  "foo" => "22",
)




   Ejemplo de Yaf_Route_Map


<?php
/**
 * Añade una ruta map a la pila de rutas llamando a addConfig
 */
$config = array(
    "name" => array(
       "type"             => "map", // ruta Yaf_Route_Map
       "controllerPrefer" => FALSE,
       "delimiter"        => "#!",
    ),
);
Yaf_Dispatcher::getInstance()->getRouter()->addConfig(
    new Yaf_Config_Simple($config));
?>
